import type { DsdReading } from "./leadership-readings";

/** Original articles read in full. New situations are fictional learning examples. */
export const leadershipArticles: Record<string,DsdReading> = {
 article_25:{title:"Giving feedback someone can use",opening:"In a practice conversation, a DSD colleague explains employment support options clearly and gives the person time to consider them. The conversation ends without clarifying who will respond next. A supervisor can recognize the thoughtful explanation and help improve the ending without turning the feedback into a judgment about confidence or personality.",sections:[
  {heading:"Put the observation beside the person's account",paragraphs:["Describe what you heard and ask how the colleague understood the moment. Perhaps they expected another team to confirm the contact, or the guidance leaves ownership unclear. Their explanation may reveal something you could not see from the exchange alone.","Make the expectation concrete: the person should have an understandable next step and a way to ask what remains uncertain. Invite the colleague to try wording that sounds natural to them. A slower conversation with needed communication support should not be treated as poor performance simply because it takes longer."]},
  {heading:"Provide the support the next attempt needs",paragraphs:["Arrange access to accurate guidance, a current contact route or relevant coaching. Give the colleague space to correct your interpretation. A power difference can make that harder, so explain how feedback notes will be used and keep this learning exercise separate from personnel records.","When the skill is used again, examine what became clearer for the person receiving the explanation. Recognize specific progress as well as unresolved concerns. Use the applicable supervisory process for actual performance matters; a practice exercise is an opportunity to learn, not an employee rating."]},
 ],guide:"leadership",sources:["communication","development","accommodation"]},
 article_26:{title:"Making it possible to raise a concern",opening:"A new DSD employee finds two different contact instructions in published guidance. Reporting the discrepancy may draw attention to an error the team missed. The supervisor's response can help the employee feel that bringing it forward was worthwhile—and help people who may already have relied on the document.",sections:[
  {heading:"Respond to the concern and its consequences",paragraphs:["Thank the colleague, establish which version is affected and involve the person who can decide the correction. Consider both future readers and people who may need an updated explanation. Use the appropriate reporting route if the issue involves privacy or another formal responsibility.","Return with what can be shared about the response. If you approved the earlier version, acknowledge your part. Discuss process improvements without publicly blaming an individual or exposing private information."]},
  {heading:"Make the invitation credible before the next problem",paragraphs:["When assigning responsibilities, provide usable instructions, realistic capacity and a contact for uncertainty. Let staff explain what a new priority would displace. If an access concern is raised, arrange the appropriate response rather than expecting the employee to work around it indefinitely.","Look beyond the number of reports. More questions may mean people are finally able to identify existing problems; fewer may have several explanations. Ask what happened after someone spoke and whether the resulting response helped. That experience gives the next colleague a reason to come forward."]},
 ],guide:"leadership",sources:["communication","accommodation"]},
 article_27:{title:"Helping a team look beyond the first solution",opening:"More partners are asking DSD for updates on unresolved questions. The team suggests assigning another person to respond. That may help immediately, but the group also needs to understand why people are asking again. Are answers delayed, acknowledgments unclear or contact methods unusable? Different explanations call for different decisions.",sections:[
  {heading:"Compare explanations with the evidence available",paragraphs:["Ask what the records include, which experiences are missing and what changed around the same time. Hear from the team receiving transfers and, through an appropriate route, people using the information. A count of completed contacts does not tell you who could not get through.","Consider the consequence of each option. More response capacity may reduce waiting while pulling time from the work needed to resolve the underlying questions. A clearer status message may help some people but still leave an urgent or complex inquiry without an owner."]},
  {heading:"Choose a response that also helps the team learn",paragraphs:["Identify an authorized improvement, the question it will test and the conditions that would prompt a change. Keep the immediate service need visible while examining the cause. Do not ask people to wait for an evaluation before addressing an urgent responsibility.","Record the reasoning in the appropriate shared location and return with what happened. Include any burden shifted to people with disabilities, chosen supporters or partners. A useful result helps the next decision maker understand both the improvement and its limits."]},
 ],guide:"data",sources:["person","communication","ncd"]},
 article_28:{title:"Inviting people into a decision they can shape",opening:"A DSD team wants to improve how people find employment information. It could ask for comments on the current page, invite people to develop alternatives or ask them to compare proposed options. Each invitation offers different influence. People deserve to know which one is being offered before they give their time and experience.",sections:[
  {heading:"Match participation to the question",paragraphs:["Explain what remains open, the constraints and who will decide. Include people with disabilities who use different support and communication arrangements, alongside relevant staff and partners. Ask how they would like to take part; one advisory member cannot describe everyone's experience.","A discussion can help compare options, while an individual conversation or accessible written response may reveal something someone would not raise in a group. If none of the proposed options is usable, a vote between them will not solve the problem. Make room to develop another approach."]},
  {heading:"Carry the contribution into the reasoning",paragraphs:["Preserve disagreement accurately. A person who needs a written contact route and someone who prefers a scheduled call may both offer information the design needs. Check the account with participants and let them correct how their contribution is represented.","Explain what changed, what could not change and why. Identify how unresolved concerns can reach the responsible person. Keep government-to-government Tribal consultation distinct from community engagement when that responsibility applies. The measure of participation is meaningful influence and an understandable response, not simply attendance."]},
 ],guide:"outreach",sources:["person","communication","tribal","selfAdvocacy"]},
 article_29:{title:"Using authority to make participation possible",opening:"A person invited to a DSD listening session asks for a way to participate from home. The team has already arranged in-person events. A leader can treat the request as an inconvenience—or ask what would make participation useful and help staff address the barrier. The person should not have to solve the agency's arrangements to be heard.",sections:[
  {heading:"Act on the barrier without taking over",paragraphs:["Ask about the person's preferences and work with the event owner on usable options. A supervisor may be able to arrange staff time or accessible material; another decision may belong elsewhere. Take responsibility for finding the right contact and returning with an answer.","The same care applies when a person chooses a supporter or uses a communication device. Allow time and address the person directly. Help make their preferred participation possible rather than substituting a professional's idea of what is easiest."]},
  {heading:"Keep the person's priorities visible",paragraphs:["Explain which decisions are open and which remain with an authorized role. Check how the person's views will be recorded and used, following applicable consent and privacy requirements. Support can help someone direct a conversation; it should not quietly transfer that direction to someone else.","If an arrangement you approved created a barrier, acknowledge it and explain the response. Carry the lesson into the next invitation or guidance review. A useful act of leadership leaves people with greater ability to participate, not greater dependence on one leader to intervene."]},
 ],guide:"person-centered",sources:["person","communication","supportedChoice"]},
 article_30:{title:"Showing a practice others can use",opening:"A DSD supervisor asks for plain language, then shares a memo filled with unexplained abbreviations. Colleagues receive a mixed example. A more helpful model shows how to make a real instruction clearer while keeping its meaning accurate—and gives credit to the people who helped.",sections:[
  {heading:"Explain the reasoning behind the revision",paragraphs:["Choose a short, non-identifying example. Instead of saying a question will reach the appropriate team, explain who receives it, how the person will hear back and where they can ask for help. Check the details with the responsible subject expert before using the wording.","Invite a reader to explain what they would do next and where they are still unsure. Share what changed because of that response. Colleagues can then adapt the method to another situation rather than copying language that may not fit."]},
  {heading:"Notice what your recognition encourages",paragraphs:["Credit the person who identified the barrier, the colleague who checked the policy and the person who made the document accessible—not only whoever presents it. Ask whether someone wants a supported opportunity to lead the next review.","Avoid making constant availability or after-hours effort the unspoken route to recognition. Arrange time and clear decision boundaries so others can participate. A practice becomes useful across teams when people understand its purpose, can adapt it and have the support to carry it out."]},
 ],guide:"communication",sources:["communication","standard","development"]},
 article_17:{title:"Understanding what helps a colleague stay and grow",opening:"A DSD specialist enjoys helping partners understand disability services, but the same expertise keeps them covering every difficult inquiry. They would like to help develop guidance and never seem to have time. A supervisor can value their current contribution and still make room to discuss what they hope to do next.",sections:[
  {heading:"Ask about the experience behind the request",paragraphs:["Invite the colleague to describe what makes the role meaningful and what is becoming harder to sustain. The answer may concern growth, compensation, workload, access or a working relationship. Do not assume that an additional assignment is the support they want.","Distinguish what you can decide from what needs another person's authority. You may be able to arrange a supported writing opportunity or redistribute coverage. A pay or accommodation question may need a different process. Explain the next step and follow through."]},
  {heading:"Make a real choice possible",paragraphs:["If the colleague wants to explore guidance development, agree on a bounded contribution with preparation and feedback. Decide what existing responsibility will shift. Learning time that depends on finishing the same workload after hours is not the opportunity it appears to be.","Afterward, ask what the experience revealed. The colleague may want to continue, choose another direction or pursue a role elsewhere. Supporting an informed choice can strengthen relationships across the agency even when someone moves on. Use what the conversation reveals to improve conditions for those who remain."]},
 ],guide:"leadership",sources:["development","employmentTerms","accommodation"]},
 article_18:{title:"Helping the team share knowledge and judgment",opening:"One DSD specialist receives nearly every difficult question about a guidance change. Other colleagues have attended the training but have not had a supported chance to explain the change to partners. The team needs more than a list of people who completed a course; it needs opportunities to develop judgment together.",sections:[
  {heading:"Identify a decision someone can learn to make",paragraphs:["Ask the specialist to explain how they recognize a question that can be answered from guidance and one that needs an authorized interpretation. Use a fictional example, then invite another colleague to reason through a different one. Discuss uncertainty without making the exercise a test of confidence or speaking style.","Combine instruction, observation and supported practice as the situation requires. There is no need to impose a fixed learning ratio or timetable. Agree on what the learner will handle, when to seek help and how the specialist will remain available without taking over the entire assignment."]},
  {heading:"Share access to the opportunity",paragraphs:["Ask about interests and arrange usable preparation, materials and feedback. Notice who repeatedly provides coverage while others learn. A person should not miss development simply because the usual preparation meeting conflicts with their schedule or access needs.","After the next relevant situation, ask whether the colleague had the information and authority they needed. If every question still returns to the specialist, examine the handoff and decision boundaries before concluding that learning failed. The aim is more people able to contribute with appropriate support."]},
 ],guide:"orientation",sources:["development","accommodation"]},
 article_19:{title:"Understanding a concern that keeps returning",opening:"A DSD colleague has asked several times how to answer a partner's question about support options. Each time, the supervisor sends the same guidance. The colleague returns because two passages seem to name different contacts. What sounds like a repeated request may be an unresolved decision the document cannot answer.",sections:[
  {heading:"Find where the guidance stops helping",paragraphs:["Ask the colleague to walk through a fictional version of the inquiry. What is clear, where do they become uncertain and what have they already tried? Let them explain before deciding whether the issue is knowledge, confidence, access or conflicting instructions.","Coaching is useful when someone needs practice with a decision they can make. It cannot resolve a conflict that belongs to the policy or process owner. Identify the responsible person and a usable interim route for questions while the ambiguity is addressed."]},
  {heading:"Check whether the response resolved the problem",paragraphs:["Write the agreed distinction clearly enough that someone outside the conversation could use it. Invite corrections and check the next relevant example. An answer to one inquiry may help that person while leaving the general guidance gap in place.","If a new concern involves conduct, unfair treatment or an accommodation need, give it its own appropriate response. Resolving the policy question does not automatically resolve the workplace concern. A colleague should be able to bring new information without being treated as though they are simply repeating themselves."]},
 ],guide:"leadership",sources:["communication","accommodation"]},
 article_20:{title:"Being someone colleagues can rely on",opening:"A DSD colleague spots a problem in the contact instructions just before guidance is shared. The supervisor has often welcomed questions, but the colleague also remembers what happened the last time someone raised a concern under pressure. Reliability is built through those ordinary responses, not only through an invitation to speak.",sections:[
  {heading:"Make the next step dependable",paragraphs:["Acknowledge the concern and establish whether someone needs an immediate answer. Identify who can check the instruction and how the colleague will hear back. If an answer is delayed, provide an update rather than leaving them to keep asking.","Agree on routes for urgent questions and those that can wait for a discussion. Include a backup when the usual person is unavailable. Check that staff in different roles and schedules can use the arrangement, with appropriate communication access."]},
  {heading:"Repair a missed commitment",paragraphs:["If staff learned about a change from a partner rather than from the team, ask what that omission caused. They may have given outdated information or spent time finding an answer. Explain what happened, correct what you can and seek the authority needed for the rest.","Let colleagues help improve the handoff without making them responsible for the original failure. Then show what happened the next time. People can recognize a useful change while still needing more experience before they rely on the process fully."]},
 ],guide:"leadership",sources:["communication","development"]},
 article_21:{title:"Keeping disagreement from becoming exclusion",opening:"A colleague who raises questions about accessibility stops receiving invitations to a DSD guidance review. The meetings become shorter, but the unresolved question returns when partners try to use the material. A disagreement about the draft has become a decision about whose experience the team hears.",sections:[
  {heading:"Understand both the issue and the exclusion",paragraphs:["Ask the people involved for specific examples. What concern was raised, how was it handled and who changed the invitations? The need to finish a draft and the need to resolve an access barrier may both be real. Examine the barrier and the authority needed to address it.","Treat the decision to exclude a colleague as a separate matter. Clarify participation responsibilities and seek the appropriate workplace guidance if the reported conduct warrants it. A compulsory joint conversation may not be suitable when someone has raised a concern about mistreatment or retaliation."]},
  {heading:"Make participation useful again",paragraphs:["Where a working discussion is appropriate, create a clear way to raise an example, identify an unresolved question and receive a response from someone who can decide. Different ways of expressing disagreement should not determine whether relevant evidence is heard.","Check the next review. Restoring an invitation is not enough if the agenda leaves no opportunity to contribute. Ask whether the concern reached the decision and whether the colleague can continue participating without having to absorb the same barrier again."]},
 ],guide:"intercultural",sources:["communication","accommodation"]},
 article_22:{title:"Making an invitation to contribute meaningful",opening:"A DSD supervisor asks who would like to help improve an accessible guidance resource. The same two people volunteer. Another colleague has a useful idea but cannot leave inbox coverage, and someone else would prefer to review the draft in writing. Silence does not tell the supervisor what either person could contribute.",sections:[
  {heading:"Show what is open and make participation possible",paragraphs:["Explain the question, what can change and who decides. Provide usable materials and preparation time. Someone may be able to identify a confusing passage without wanting to lead the whole project. Ask what form of participation would fit their interest and responsibilities.","Arrange coverage and support before treating the opportunity as available. Consider whose contributions are less visible, including careful review, accessible document preparation and helping colleagues understand a change. A public presentation is only one way to contribute."]},
  {heading:"Return with what changed",paragraphs:["Show how suggestions shaped the result. If an idea could not be used, explain the relevant constraint and whether it could be reconsidered. Ask how contributors would like their effort acknowledged rather than assuming public recognition is welcome.","If engagement survey results prompted the discussion, use them to open a question, not to identify or challenge individual respondents. Protect confidentiality and seek several possible explanations. What matters is whether people have a usable opportunity to influence the next decision."]},
 ],guide:"leadership",sources:["development","accommodation"]},
 article_23:{title:"Helping colleagues navigate a service change",opening:"Two DSD teams will use one route for partner questions. Leaders understand the reason, but a colleague preparing a response needs to know what to do with an inquiry already in progress. Another asks whether the new system supports their assistive technology. A useful announcement starts from those practical questions.",sections:[
  {heading:"Explain what changes and who can help",paragraphs:["State the confirmed change, its applicable effective date, the current instructions and the decisions staff still make. Distinguish an unresolved question from a settled decision. Give people a responsible contact rather than a general assurance that more information will come.","Walk through a fictional inquiry that begins under the old process and continues under the new one. Include communication preferences, an urgent question and an unavailable contact. Identify gaps before colleagues or partners have to improvise. A staffing question deserves an authorized response of its own."]},
  {heading:"Listen during actual use",paragraphs:["Make it easy to raise an emerging problem without waiting for a polished explanation. Check whether staff can access the tools and whether the receiving team accepts the handoff. Address barriers through the responsible process and keep shared guidance current.","Compare routine and more complex inquiries. A faster average can hide an additional transfer for someone who needs communication support. Bring both experiences to the change owner, explain the proposed adjustment and report the decision to the people who helped identify it."]},
 ],guide:"service-design",sources:["communication","standard"]},
 article_24:{title:"Helping a new colleague find their footing",opening:"A new DSD employee understands disability services but does not yet know who approves a partner response or where to raise an inaccessible system. A warm welcome includes those practical connections. Questions often become clearer after someone has had a chance to try the role.",sections:[
  {heading:"Make the first responsibilities understandable",paragraphs:["Provide usable materials, equipment access and a named person for everyday questions. Explain the distinction between a peer who can demonstrate routines and the supervisor who remains responsible for priorities, expectations and feedback.","Use a fictional partner inquiry to practice finding current guidance, explaining it clearly and recognizing when to ask for an authorized interpretation. Give room to revise before anything is sent externally. If experienced colleagues give conflicting instructions, resolve that difference rather than asking the newcomer to choose whom to believe."]},
  {heading:"Let support develop with the role",paragraphs:["Ask what has become easier and what the colleague has not yet had a chance to try. Adjust support as new responsibilities arise instead of imposing a separate calendar of check-ins. Keep a dependable way to ask for help and discuss individual access needs privately through the appropriate process.","When the colleague identifies something they learned only by chance, use that insight to improve the welcome for the next person. Check whether the revised instruction is understandable and accessible. Successful orientation helps people contribute with confidence while making the team easier to join."]},
 ],guide:"orientation",sources:["development","accommodation","standard"]},
 article_09:{title:"Listening when a colleague needs support",opening:"After speaking with a partner about a person's difficulty finding usable employment information, a DSD colleague seems upset. You have ideas for improving the guidance, but first ask what was hardest. They explain that another colleague dismissed the person's concern. The answer changes what support is needed.",sections:[
  {heading:"Let the colleague correct your understanding",paragraphs:["Give the conversation your attention and reflect what you heard: “It sounds as though the response to the access concern is what stayed with you. Have I understood?” A question leaves room for the person's account. An immediate solution can unintentionally close that space.","Ask what response would help, and be clear about any responsibility you have to act. Explain what needs to happen next without asking for unnecessary personal or case information. Listening and accountability can belong in the same conversation."]},
  {heading:"Support the person and address the consequence",paragraphs:["Suppose the colleague also promised a reply date they could not verify because they wanted to reassure the partner. Acknowledge the care behind the response while helping correct the uncertain promise. Find out who can confirm the next step and who will communicate it in a usable way.","Return separately to the colleague's experience. They may want time to think, a practical change or help raising a workplace concern. Do not assume that praise or advice is what they need. Follow up on the issue they actually raised, and accept a correction if the first response missed it."]},
 ],guide:"leadership",sources:["communication","wellbeing"]},
 article_10:{title:"Learning from how people use what you create",opening:"You prepare DSD guidance carefully, and a colleague often improves the final draft by making the next step clearer. Instead of simply accepting the edits, you ask what they noticed. Their explanation opens a practical learning opportunity: understanding where a reader has to supply information the document never gives them.",sections:[
  {heading:"Find a question you can explore",paragraphs:["Choose a draft that can be discussed safely. Ask a reader to show where they became unsure and what they thought the sentence meant. “Too technical” becomes more useful when someone can point to a term, an unexplained responsibility or a missing contact route.","Include a different perspective. A partner who explains guidance to people with disabilities may notice something the writing team misses. Accessibility review may reveal a separate barrier. One reader's successful experience does not show that the document works for everyone."]},
  {heading:"Practice, then look at the effect",paragraphs:["Revise a bounded part of the draft and ask whether the reader can now identify the next action. Seek help from an editor, policy owner or accessibility colleague where needed. Agree on any approval required before the guidance is used.","Carry one useful technique into the next draft and remain open to new questions. If the same problem comes from a template or conflicting source material, bring that to the person who owns it. Personal learning and improvements to the team's tools can support one another."]},
 ],guide:"communication",sources:["communication","standard","development"]},
 article_11:{title:"Making room for different ways of communicating",opening:"During a DSD review meeting, a colleague looks away while listening to a service-design proposal. Someone interprets that as disengagement. The colleague may be concentrating, managing sensory demands or thinking through the information; the group does not know. What they can do is make it easier to ask questions and participate.",sections:[
  {heading:"Separate what you notice from what you infer",paragraphs:["A movement, pause or change in tone can draw your attention without explaining a person's intention. Notice your own reaction first. If you feel rushed or challenged, ask what information you need before responding. Do not use eye contact, stillness or rapid speech as measures of care or capability.","Offer a practical choice: “Would it help to review the draft separately before discussing the options?” Advance materials, clear questions and time to respond may help several people. Individual access needs may call for an additional conversation through the appropriate process."]},
  {heading:"Repair the effect of a misunderstanding",paragraphs:["If a colleague says your response made them feel dismissed, acknowledge the effect and ask what went unheard. Explaining your intention can add context, but it does not resolve the missed concern. Make room to address it and agree how similar questions can be raised.","A supervisor has particular influence over whether staff feel able to correct an error or identify a barrier. Welcome the relevant information, check it and explain what changed. People should not have to communicate in one preferred style to have a valid concern taken seriously."]},
 ],guide:"intercultural",sources:["communication","accommodation"]},
 article_12:{title:"Supporting people to sustain meaningful service",opening:"After a demanding discussion about gaps in disability supports, one DSD colleague wants to talk through what happened. Another would prefer a quiet pause before returning to it. A supportive team can make room for both while ensuring that any urgent follow-up has an owner.",sections:[
  {heading:"Make support usable in an ordinary busy day",paragraphs:["Ask what would help rather than assuming everyone recovers or reflects in the same way. A supervisor can clarify coverage, priorities and how to raise a concern when the usual contact is unavailable. A general invitation to take a break is less useful when no one knows who will handle the next request.","Check the effect on colleagues providing cover. An arrangement that repeatedly shifts pressure to someone with less influence needs attention. Keep personal reactions and private circumstances out of routine handoff notes; share only what is needed to continue the service response."]},
  {heading:"Address the conditions as well as the individual need",paragraphs:["People may choose support through trusted relationships or the state's employee assistance resources. They should not have to discuss health details in a team exercise. Managers can keep workplace conversations focused on responsibilities, access, support and what can change.","If the same strain returns, examine staffing, unclear guidance and unresolved service barriers. Personal coping cannot supply missing decision authority or resources. Bring those issues to someone who can act, and return to the team with the response. Sustaining humane service includes caring for the people responsible for it."]},
 ],guide:"leadership",sources:["wellbeing","accommodation"]},
 article_13:{title:"Seeing the wider effect of a small decision",opening:"Questions about a revised DSD guide are increasing. Adding help may be useful now, but a colleague asks what is causing people to return. Is an instruction unclear? Is the contact route inaccessible? Has something else changed? Strategic thinking begins with curiosity about the experience behind the count.",sections:[
  {heading:"Follow the question across the process",paragraphs:["Look at what the records actually show and who may be missing. A shorter response time could mean better help, or it could mean people are being directed elsewhere without an answer. Ask the receiving team what happens next and seek people's experience through an appropriate, accessible route.","Keep explanations open. A rise in questions after a new guide may relate to wording, outreach, staffing or more than one change. Describe what supports the explanation and what remains unknown. Avoid collecting private information that is unnecessary for the review."]},
  {heading:"Recommend something the evidence can support",paragraphs:["A small test with fictional guidance can reveal whether readers understand a next step. It does not establish how often the barrier occurs across services. Bring the findings, limits and proposed response to the person who can authorize a change.","Consider who would gain time and who might inherit more effort. A process that looks efficient inside DSD may still ask a person to repeat information or coordinate several contacts. Keep a clear record of the reasoning in the approved location so future colleagues can understand why the decision was made and what might warrant revisiting it."]},
 ],guide:"data",sources:["person","communication","ncd"]},
 article_14:{title:"Turning a concern about change into useful information",opening:"A DSD team proposes a shared route for partner questions. An experienced colleague worries that people will lose the continuity they had with a named contact. The concern may reflect a real gap, uncertainty about the new process or both. It is worth exploring without labeling the colleague as resistant.",sections:[
  {heading:"Describe the experience you want to protect",paragraphs:["Choose a fictional example that makes the concern visible. A person asks for a written response, but the request is transferred without that information. Who will notice the preference, arrange support and explain what happens next? Ask someone familiar with the new process to walk through the example.","The answer may resolve the concern or identify a needed change. Separate questions about access and rights that require action before use from questions an approved trial can help answer. A trial should not be used to postpone addressing a known obligation."]},
  {heading:"Leave room to revise your view",paragraphs:["Explain the concern through a route that can act on it. Informal criticism combined with public reassurance leaves colleagues unsure what to follow. Be clear about what is known, what still needs attention and who is responding.","Invite people to describe both something that helps and something that remains difficult. They should not have to defend their first reaction throughout the change. When a decision is made, explain the reasons and what evidence would prompt another look. Being heard does not always mean a suggestion is adopted, but it should mean the concern receives a considered response."]},
 ],guide:"service-design",sources:["person","communication"]},
 article_15:{title:"Responding when the demands are no longer workable",opening:"A DSD colleague answers complex partner questions, helps new staff and repairs confusing guidance, then finishes their own assignments after hours. Much of that contribution is absent from the workload report. When they say the arrangement is becoming difficult to sustain, the team needs to understand the demands and decide what can change.",sections:[
  {heading:"Make the hidden demands visible",paragraphs:["Describe a recurring demand, what it displaces and where competing expectations arise. A colleague can raise the effect on their ability to complete responsibilities without giving a health explanation. Supervisors should listen to the actual work and avoid assuming a diagnosis or lack of commitment.","Clarify which responsibilities take priority, what can be reassigned and what requires a wider staffing or service decision. Explain how urgent matters will be handled when the agreed plan cannot be followed. A boundary becomes more usable when colleagues know how to support it."]},
  {heading:"Return with a response people can use",paragraphs:["Check whether the change helped or merely moved the burden to another colleague. If staff still lack reliable information to give partners, keep addressing that service condition as well as workload. Unresolved expectations can remain difficult even when the number of requests falls.","Employee assistance and well-being resources offer another route for personal support; use their current information to understand access and privacy. That support does not replace a manager's responsibility to address conditions within their control. The purpose is a sustainable way to provide thoughtful service, with help available when it is needed."]},
 ],guide:"leadership",sources:["wellbeing","accommodation"]},
 article_16:{title:"A development plan that helps you take the next step",opening:"A DSD analyst wants to become more confident facilitating discussions about accessible guidance. “Build leadership skills” expresses the interest but does not identify an opportunity. A useful development plan helps the analyst and supervisor agree on what to practice, the support required and how they will learn from the experience.",sections:[
  {heading:"Connect the goal to a meaningful experience",paragraphs:["The analyst might observe a facilitator, prepare questions with a mentor and lead part of a discussion while the options remain open. An observable goal could be to help participants explain an access concern and show how that concern informed the recommendation.","Include both sides of the agreement. The employee prepares and seeks feedback; the supervisor helps arrange the opportunity, time, access and an appropriate person to support it. MMB's development procedure provides the framework for individual development plans. Use the agency's process rather than adding a separate One DSD schedule."]},
  {heading:"Use what happens to guide the next choice",paragraphs:["Discuss the attempt when there is useful feedback. What became clearer? Could participants contribute in ways that worked for them? Was the decision still open to influence? A well-facilitated conversation may reveal that a project needs to invite participation earlier.","If the assignment changes or disappears, find another suitable way to practice the capability. Record the support that remains needed as well as the employee's next action. Keep the plan focused enough to guide an opportunity when it arises, without turning reflection into another reporting burden."]},
 ],guide:"orientation",sources:["development","accommodation"]},
 article_01:{title:"Finding a useful starting point for disagreement",opening:"A DSD team is ready to share employment guidance with partners. One colleague asks for another accessibility review; another worries that delaying it will leave people without timely information. Both want the guidance to help. Before deciding that one is being difficult, it helps to understand the consequence each person is trying to prevent.",sections:[
  {heading:"Bring the concern into view",paragraphs:["Ask the reviewer to show the barrier and the release owner to explain the timing concern. Perhaps the contact details are embedded in an image, while partners need an answer before a scheduled information session. The team now has something specific to resolve: how people can receive timely information they can actually use.","Describe the problem without assigning motives. Saying that the contact route is inaccessible invites a different conversation from saying that someone does not care about disability. Stay clear about the observed barrier while leaving room to learn how it happened."]},
  {heading:"Find an approach within the team's authority",paragraphs:["The content owner may be able to provide an accessible interim explanation while the complete guide is reviewed. Another concern may require the policy owner, accessibility specialist or procurement contact. Identify what can change now, who needs to decide the rest and when the team will return to it.","Listening does not require treating every option as equally suitable. Explain why an approach would leave a barrier unresolved or conflict with an applicable requirement. A collaborative conversation can clarify a problem; it does not create authority to waive a requirement."]},
  {heading:"Notice when more than a disagreement is involved",paragraphs:["The situation changes if a colleague says they are mocked or excluded for raising access concerns. A supervisor should not simply ask them to resolve that with the other person in public. Listen, explain the appropriate workplace route and seek guidance consistent with the concern. A colleague without supervisory authority can help identify support without promising an outcome.","After the immediate decision, check both interests: did people receive usable information, and did they receive it when needed? Let the colleague who raised the concern know what happened. That follow-through helps make future questions welcome."]},
 ],guide:"communication",sources:["communication","standard"]},
 article_02:{title:"Considering the next chapter of a DSD career",opening:"An experienced DSD specialist enjoys untangling complex guidance and helping colleagues understand it. They also want to talk honestly about pay and future opportunities. Reaching the top of a range does not answer whether they want to supervise, deepen their expertise or explore another role. Those are related questions, and each deserves attention.",sections:[
  {heading:"Describe the responsibility that has changed",paragraphs:["Bring a few recurring examples and the current position description to a conversation with the supervisor or HR. Perhaps the specialist now coordinates interpretations across teams rather than answering questions from established guidance. Explain who assigns that responsibility, how often it occurs and who holds final authority.","Keep workload, performance, classification and compensation questions distinct. More volume does not by itself explain a change in the nature of a role. Use the applicable process to explore whether the description still fits, and do not assume a review will lead to a particular classification or pay outcome."]},
  {heading:"Explore what a move would mean day to day",paragraphs:["Ask people in potential roles about the decisions they make, the preparation involved and the parts of the role they find difficult. A supervisory position may offer opportunities to develop others while leaving less time for technical analysis. A specialist or project role may offer a different kind of influence.","Consider practical conditions as well: compensation, schedule, accessible tools, support and the balance of responsibilities. MMB's career references and the applicable labor agreement or pay plan provide starting points. Confirm the details of a specific opportunity with the responsible HR contact."]},
  {heading:"Agree on a next step that respects the person",paragraphs:["A mentoring or knowledge-sharing assignment can be valuable, but it should not become a substitute for answering a pay question. If the colleague is asked to train successors, discuss what responsibilities will shift, what they will learn and how the contribution will be recognized.","End with an action each person can take: a role conversation, a review question for HR or a supported chance to observe a different responsibility. Keep the compensation question visible until it receives an answer. A meaningful career conversation leaves room for the person to choose what matters to them."]},
 ],guide:"orientation",sources:["careers","employmentTerms","accommodation"]},
 article_03:{title:"Explaining how you contribute to DSD's mission",opening:"At a meeting with new partners, a job title may not explain when someone should come to you. A clearer introduction might begin, “I help our team make disability services guidance easier to understand and use.” A short example can then show what that contribution means and where your authority ends.",sections:[
  {heading:"Start with a contribution people can recognize",paragraphs:["Think of something you can describe without private information. Perhaps a team revised a support guide and your contribution was noticing that the written instructions did not match the contact route. Describe that part accurately and share credit for the team's result.","Connect the contribution to its purpose: helping people understand choices, making an access concern visible or helping a colleague provide a reliable response. You do not need a slogan or an impressive title. A specific account is often easier for someone else to remember and use."]},
  {heading:"Make the introduction fit the conversation",paragraphs:["A colleague may need to know when to involve you in a draft. A hiring panel may need an example of a capability. A person with a service question needs to know whether you can answer it or connect them with someone who can.","For example: “I work on how our guidance explains the next step. I can bring a confusing instruction back to the content team. Questions about an individual decision need the responsible service contact.” That wording offers help without implying authority you do not have."]},
  {heading:"Leave room for a response",paragraphs:["Try a brief spoken or written version and ask a colleague what they would contact you about after hearing it. If their understanding differs from what you intended, adjust the words. Use a format and pace that work for you; a rapid spoken pitch is not the only useful way to introduce a contribution.","In conversation, allow time and a usable way for the other person to respond. Eye contact, speech or facial expression alone does not tell you whether someone is interested or understands. A good introduction begins a connection rather than testing how someone communicates."]},
 ],guide:"communication",sources:["person","communication"]},
 article_04:{title:"Making a development conversation useful",opening:"A DSD colleague wants to learn how to facilitate conversations with disability-led organizations. Their supervisor is supportive, but the request keeps ending with “let's revisit it.” A more specific discussion can reveal whether the obstacle is time, funding, preparation or uncertainty about the opportunity.",sections:[
  {heading:"Name what the experience would help you learn",paragraphs:["Explain the skill you want to develop and why it matters. You might want to help participants understand what is open for discussion, make room for different communication methods or report back on a difficult decision. These call for more than attending a meeting.","Propose an experience with support: observe a facilitator, help prepare an accessible agenda, lead a short part of a session and discuss the response afterward. Identify needed approvals, preparation, access arrangements and who can provide feedback."]},
  {heading:"Discuss the conditions honestly",paragraphs:["Ask what time, coverage or funding is available and what responsibilities would need to shift. If the answer is not yet, clarify what would make a decision possible and agree on a date to return. If readiness is the concern, ask for a relevant example and an opportunity to practice with support.","MMB's employee development procedure describes responsibilities shared among employees, supervisors and agencies. Use the agency's development and approval processes to record the agreed next step. A learning plan should connect the person's growth with the needs of the team and the public it serves."]},
  {heading:"Make opportunity easier to find",paragraphs:["Supervisors can consider who hears about assignments and whose schedule or access needs are overlooked. An opportunity mentioned only in an informal conversation may never reach a qualified, interested colleague. Explain criteria, support and timing through usable channels.","After the experience, talk about what the colleague learned and what support made it possible. If they were not selected, explain the decision appropriately and consider another way to develop the capability. Encouragement becomes more useful when someone can see a next step."]},
 ],guide:"orientation",sources:["development","accommodation"]},
 article_05:{title:"Growing through expertise and contribution",opening:"A DSD specialist enjoys making complicated disability services guidance understandable. They like helping colleagues, but are unsure whether supervising a team is the direction they want. Leadership can also grow through technical judgment, thoughtful collaboration and knowledge that helps others make better decisions.",sections:[
  {heading:"Look closely at what interests you",paragraphs:["Think about a recent experience that held your attention. Was it interpreting the guidance, hearing what people found confusing, writing an explanation or helping the group reach a decision? Different parts of the same project can point toward different opportunities.","Talk with colleagues in roles you are considering. Ask about an ordinary day, a difficult decision and what they can approve themselves. Review actual duties and employment terms rather than assuming that a different title or lateral move brings higher pay or more authority."]},
  {heading:"Try a bounded experience with support",paragraphs:["You might help test a revised partner guide, co-facilitate a learning session or explore how an access concern moves from staff to a system owner. Agree on the purpose, time, access arrangements and feedback. Discuss what will shift in your existing responsibilities.","Experienced colleagues can become the people everyone relies on for urgent repairs. That contribution deserves recognition, but repeatedly solving the same problem under pressure may offer little opportunity to develop. Ask what new judgment or skill the proposed assignment will let you practice."]},
  {heading:"Use the experience to make an informed choice",paragraphs:["Keep a short, non-identifying account of what you contributed, whose expertise helped and what the decision maker did with the recommendation. If it was not adopted, ask what constraint or evidence mattered. That can reveal a useful learning need or a limit outside your role.","Share credit and discuss what you would like to do more of. The experience may point toward another position or toward a richer role where you are. Either can be a thoughtful choice when it reflects your interests, practical needs and the contribution you want to make."]},
 ],guide:"orientation",sources:["careers","development","employmentTerms"]},
 article_06:{title:"Exploring a direction for your career",opening:"A colleague finds that the most meaningful part of a DSD project was returning to people with disabilities to explain what changed because of their input. They wonder whether more community engagement would suit them. That interest is worth exploring, including the preparation and follow-through that are less visible than the public meeting.",sections:[
  {heading:"Turn an interest into a question",paragraphs:["Choose something you could learn through a conversation or a supported experience. For example: would you enjoy coordinating access arrangements and following up on unresolved questions as well as facilitating the gathering? Ask someone doing the role to describe those responsibilities.","Bring your own experience into the discussion. What did you contribute, what was satisfying and what required help? Feedback from colleagues can add another perspective without defining the only path available to you."]},
  {heading:"Ask for the kind of support you need",paragraphs:["A mentor may help you understand a role. A supervisor may arrange approved time and coverage. A sponsor may connect your experience to an appropriate opportunity. These forms of support overlap, but a helpful relationship does not automatically include authority to assign or fund something.","Propose a manageable next experience, such as drafting the report-back from one engagement session with the lead's review. Agree on responsibilities, access needs, privacy and feedback before taking it on. Learning should not depend on silently adding work to an already full schedule."]},
  {heading:"Let the experience change the plan",paragraphs:["Afterward, consider both the contribution and the fit. Perhaps you enjoyed analyzing feedback more than leading discussion. Perhaps coordinating an understandable response felt meaningful, even when the answer was difficult. Use those observations to shape the next conversation.","Supervisors can help by making opportunities visible and explaining relevant criteria. Employees should not need an informal connection to learn what is possible. A career plan can evolve while continuing to support the division's mission and the person's goals."]},
 ],guide:"outreach",sources:["development","careers","accommodation"]},
 article_07:{title:"Building trust through dependable action",opening:"A DSD supervisor invites interest in a project reviewing accessible guidance, then fills the assignment before the announced deadline. A colleague who was preparing to apply is disappointed. The person selected did not control the timing but now feels uncomfortable. Trust depends on how the supervisor responds to both experiences and the commitment the team saw.",sections:[
  {heading:"Name the commitment that was missed",paragraphs:["Acknowledge the difference between the invitation and what happened. Explain what can be shared about the decision without disclosing private information. Ask what consequences you may have overlooked, while taking responsibility for the part within your control.","An employee may have lost a rare chance to demonstrate a skill. Another may now doubt that future deadlines matter. A correction to the announcement alone may not address either concern. Work with the appropriate process to identify what can still be remedied and when people will hear back."]},
  {heading:"Make the next process reliable",paragraphs:["Clarify criteria, timing, support and how interested colleagues can participate. If circumstances change, communicate promptly through the same usable channels as the invitation. Confirm that people had a practical opportunity to respond, including those who were absent or needed preparation time.","Protect the selected colleague from being made responsible for the process failure. A leader can explain and repair a decision without inviting staff to speculate about another employee's qualifications or private circumstances."]},
  {heading:"Look at the pattern, not only one relationship",paragraphs:["People may trust a supervisor's technical knowledge while questioning how opportunities are allocated. They may feel supported by one colleague while finding an organizational process unreliable. Ask what needs to become more dependable and who has authority to change it.","Follow through on the next commitment and return with what happened. If similar concerns recur across teams, bring the pattern to the responsible leader. Trust grows through actions people can observe; it should not require asking them to set aside an unresolved concern."]},
 ],guide:"leadership",sources:["development","accommodation"]},
 article_08:{title:"Responding thoughtfully when plans change",opening:"A DSD supervisor learns that a partner guidance update is moving forward sooner than expected. Staff immediately ask whether the materials will be accessible and what they should tell people who already received the earlier version. The supervisor feels pressure to reassure everyone. A quick guess, however, could become the instruction partners rely on.",sections:[
  {heading:"Give people what is known and a way forward",paragraphs:["Pause long enough to separate confirmed information from questions. A useful opening might be: “The release date has changed. I am checking which materials are ready and what partners need now. Which decisions cannot wait until our next update?” State when you will return and who is checking each issue.","Where immediate direction is needed, stay within your authority and make its limits clear. Do not promise that a barrier is resolved before it has been checked. Staff need a dependable route for urgent questions as well as reassurance that someone is taking responsibility."]},
  {heading:"Notice how your response lands",paragraphs:["Some people speak quickly when surprised; others become quiet or think aloud. Colleagues may interpret those habits as instructions or as unavailability. Ask someone you trust what they heard you authorize, rather than asking only whether you appeared calm.","In a fictional rehearsal, practice a response and invite the other person to explain what they would do next. A mismatch gives you something concrete to revise. Communication style varies, and outward composure alone does not show understanding or good judgment."]},
  {heading:"Correct an assurance and examine the process",paragraphs:["If you gave an inaccurate answer, return to the people who received it, explain the correction and check what action they took. Coordinate the updated message through the appropriate channels so staff and partners are not left with conflicting versions.","Later, ask whether the event revealed a recurring gap in how changes reach the team. Personal reflection can improve a response, but cannot replace timely information, accessible materials or a clear implementation decision. Give the wider issue an owner and a next review point."]},
 ],guide:"leadership",sources:["communication","standard","development"]},
};
